(4173467, 601012, 68947, '<td valign="top">CUTE!  I might have cropped out the hand and just gotten the pencil, but really creative.  I like it!</td>', 'CUTE!  I might have cropped out the hand and just gotten the pencil, but really creative.  I like it!', '2007-10-17 01:20:58.000000', NULL, 1),
