(4173483, 599003, 77192, '<td valign="top">it''s a good shot, might not be obvious to some which one the actual pencil is..</td>', 'it''s a good shot, might not be obvious to some which one the actual pencil is..', '2007-10-17 01:23:04.000000', NULL, 1),
(4173487, 600981, 32872, '<td valign="top">Love your DOF...the clippings really add to your image.  Nice lighting and tones. I like!!  :)</td>', 'Love your DOF...the clippings really add to your image.  Nice lighting and tones. I like!!  :)', '2007-10-17 01:23:18.000000', NULL, 1),
(4173489, 599966, 77192, '<td valign="top">title says it all</td>', 'title says it all', '2007-10-17 01:23:34.000000', NULL, 1),
(4173491, 600981, 68947, '<td valign="top">To me, this still shows a pencil as a pencil and I''m not sure but, I think the challenge called for a non-pencil usage in the shot.  Nice shot though!</td>', 'To me, this still shows a pencil as a pencil and I''m not sure but, I think the challenge called for a non-pencil usage in the shot.  Nice shot though!', '2007-10-17 01:23:51.000000', NULL, 1),
