(4173808, 600580, 85155, '<td valign="top">This is a great composition, and I like the blue tray and cup, but the chopstick thing was overdone on this challenge.</td>', 'This is a great composition, and I like the blue tray and cup, but the chopstick thing was overdone on this challenge.', '2007-10-17 03:03:11.000000', NULL, 1),
(4173810, 600945, 85155, '<td valign="top">For me everything is way to out of focus, in fact, at least at this resolution, it doesn''t look like anything is in focus.  I like the shot, but I would like to see more of the board the pencil is stuck in.</td>', 'For me everything is way to out of focus, in fact, at least at this resolution, it doesn''t look like anything is in focus.  I like the shot, but I would like to see more of the board the pencil is stuck in.', '2007-10-17 03:04:08.000000', NULL, 1),
(4173811, 600014, 85155, '<td valign="top">This seems like you are trying to stretch to meet the topic, the pencil doesn''t really seem to be a match, it is just by some matches.</td>', 'This seems like you are trying to stretch to meet the topic, the pencil doesn''t really seem to be a match, it is just by some matches.', '2007-10-17 03:04:51.000000', NULL, 1),
(4173814, 599675, 85155, '<td valign="top">This is a pretty decent shot, I would have liked to see maybe some other darts, or maybe even other pencils as darts.</td>', 'This is a pretty decent shot, I would have liked to see maybe some other darts, or maybe even other pencils as darts.', '2007-10-17 03:05:19.000000', NULL, 1),
(4173816, 600832, 85155, '<td valign="top">I''m not sure what the pencil is supposed to be in this shot.</td>', 'I''m not sure what the pencil is supposed to be in this shot.', '2007-10-17 03:06:06.000000', NULL, 1),
(4173819, 600113, 85155, '<td valign="top">Sorry, I think the chopstick thing was way overdone this time around.  I like the variety of colors though.</td>', 'Sorry, I think the chopstick thing was way overdone this time around.  I like the variety of colors though.', '2007-10-17 03:06:32.000000', NULL, 1),
(4173820, 599211, 85155, '<td valign="top">I''m having a hard time telling what the pencils are supposed to be.  Overall I like the picture, except for the pencil on the left, it doesn''t seem to fit here.  I really like the contrast of the pencils against the wood though.</td>', 'I''m having a hard time telling what the pencils are supposed to be.  Overall I like the picture, except for the pencil on the left, it doesn''t seem to fit here.  I really like the contrast of the pencils against the wood though.', '2007-10-17 03:07:26.000000', NULL, 1),
(4173821, 601228, 85155, '<td valign="top">I like the point of view on this shot.  It is an interesting composition, but the chopstick thing was way overdone this time around.</td>', 'I like the point of view on this shot.  It is an interesting composition, but the chopstick thing was way overdone this time around.', '2007-10-17 03:08:10.000000', NULL, 1),
(4173822, 600721, 85155, '<td valign="top">Where''s the pencil?</td>', 'Where''s the pencil?', '2007-10-17 03:08:26.000000', NULL, 1),
(4173823, 601073, 85155, '<td valign="top">This is a pretty cool affect, nicely done on the composition.  I''m just not sure why we are only seeing a quarter of a circle, where''s Saturn?</td>', 'This is a pretty cool affect, nicely done on the composition.  I''m just not sure why we are only seeing a quarter of a circle, where''s Saturn?', '2007-10-17 03:09:17.000000', NULL, 1),
(4173826, 600951, 85155, '<td valign="top">The pencil is supposed to be something other than a pencil, these are just a bunch of erasers, I like the colors though.  And the symmetry works for me.</td>', 'The pencil is supposed to be something other than a pencil, these are just a bunch of erasers, I like the colors though.  And the symmetry works for me.', '2007-10-17 03:10:07.000000', NULL, 1),
(4173829, 600076, 48228, '<td valign="top">I little bit over the top for me, and I can''t even look at it.</td>', 'I little bit over the top for me, and I can''t even look at it.', '2007-10-17 03:10:51.000000', NULL, 1),
