(4174378, 600581, 23251, '<td valign="top">Great inventive idea.  Good lighting (I don''t mind the shadow some will).</td>', 'Great inventive idea.  Good lighting (I don''t mind the shadow some will).', '2007-10-17 08:25:21.000000', NULL, 1),
(4174379, 601247, 38032, '<td valign="top">Great idea and great composition. A bit more contrast would make this pop a bit more (if whites were more white).  I also kinda wonder how in the world this was done.</td>', 'Great idea and great composition. A bit more contrast would make this pop a bit more (if whites were more white).  I also kinda wonder how in the world this was done.', '2007-10-17 08:25:50.000000', NULL, 1),
