(4175874, 600826, 32872, '<td valign="top">Great idea...fabulous idea!! I wish this were more in focus though. I love your composition.</td>', 'Great idea...fabulous idea!! I wish this were more in focus though. I love your composition.', '2007-10-17 15:38:23.000000', NULL, 1),
(4175876, 600809, 32872, '<td valign="top">Wow, a house made of pencils?!  This has to be the most creative use of a pencil!  I only wish the lighting were better, but I love the detail on the pencil.</td>', 'Wow, a house made of pencils?!  This has to be the most creative use of a pencil!  I only wish the lighting were better, but I love the detail on the pencil.', '2007-10-17 15:40:45.000000', NULL, 1),
