(4177147, 600246, 41675, '<td valign="top">Although the grays look a little flat, I like the smoke. It adds to the concept of the pencil being a cigarette.</td>', 'Although the grays look a little flat, I like the smoke. It adds to the concept of the pencil being a cigarette.', '2007-10-17 23:41:38.000000', NULL, 1),
(4177150, 601044, 41675, '<td valign="top">I like your idea. For me though, the background is a little too blurred.</td>', 'I like your idea. For me though, the background is a little too blurred.', '2007-10-17 23:42:38.000000', NULL, 1),
(4177151, 601202, 6519, '<td valign="top">Congratulations, you are my 30.000th vote !!! I cherry picked this one, so I could vote high on a photo I like  :-)</td>', 'Congratulations, you are my 30.000th vote !!! I cherry picked this one, so I could vote high on a photo I like  :-)', '2007-10-17 23:43:06.000000', NULL, 1),
(4177155, 599777, 41675, '<td valign="top">I like the texture created on the left and in the center. For me, that''s the most interesting part of your photo. As far as the pencil communicated as something other than a pencil? Eh....a bit of a stretch. :-)</td>', 'I like the texture created on the left and in the center. For me, that''s the most interesting part of your photo. As far as the pencil communicated as something other than a pencil? Eh....a bit of a stretch. :-)', '2007-10-17 23:44:47.000000', NULL, 1),
(4177158, 600231, 41675, '<td valign="top">:-) I really like your idea. The tan background doesn''t do much to enhance your photo, but I like the "root" at the bottom of the glass and the "branch" on the pencil. It shouws creativity.</td>', ':-) I really like your idea. The tan background doesn''t do much to enhance your photo, but I like the "root" at the bottom of the glass and the "branch" on the pencil. It shouws creativity.', '2007-10-17 23:45:50.000000', NULL, 1),
