(4177213, 600829, 41675, '<td valign="top">For me, the focus of your image is the plant and the pencil is merely a background element and gets kind of..."lost." Again though, just the way I see it. I do like the lighting and the use of black &amp; white.</td>', 'For me, the focus of your image is the plant and the pencil is merely a background element and gets kind of..."lost." Again though, just the way I see it. I do like the lighting and the use of black & white.', '2007-10-18 00:14:30.000000', NULL, 1),
(4177217, 600383, 41675, '<td valign="top">Eww! thank goodness my Mom never made me a lunch like that! Yucky! Aside from that, I like the lighting and composition.</td>', 'Eww! thank goodness my Mom never made me a lunch like that! Yucky! Aside from that, I like the lighting and composition.', '2007-10-18 00:15:50.000000', NULL, 1),
(4177221, 601131, 41675, '<td valign="top">Good, strong black &amp; white image. Maybe a little blown out on the bowl - the base on the left hand side seems to have "disappeared."</td>', 'Good, strong black & white image. Maybe a little blown out on the bowl - the base on the left hand side seems to have "disappeared."', '2007-10-18 00:16:50.000000', NULL, 1),
(4177223, 600624, 41675, '<td valign="top">Lol - funny photo. I like the vibrant colors, "afros" and the background works well. The title ties it all together. Very creative and a fun photo to look at. Good luck in the challenge.</td>', 'Lol - funny photo. I like the vibrant colors, "afros" and the background works well. The title ties it all together. Very creative and a fun photo to look at. Good luck in the challenge.', '2007-10-18 00:17:52.000000', NULL, 1),
(4177225, 599617, 41675, '<td valign="top">The first thing that jumps out at me with your photo is the great color contrasts. Then, the balanced composition and lighting. All in all, a good photo and creatively done. I hope it does well in the challenge. 10! :-)</td>', 'The first thing that jumps out at me with your photo is the great color contrasts. Then, the balanced composition and lighting. All in all, a good photo and creatively done. I hope it does well in the challenge. 10! :-)', '2007-10-18 00:18:50.000000', NULL, 1),
(4177228, 600560, 41675, '<td valign="top">Awww, what a cutie. It took me a moment for my eyes to find the pencil. she''s so sweet I truly only see her face and that fun dress.</td>', 'Awww, what a cutie. It took me a moment for my eyes to find the pencil. she''s so sweet I truly only see her face and that fun dress.', '2007-10-18 00:20:07.000000', NULL, 1),
