(4177235, 601152, 41675, '<td valign="top">the lighting is a litte strong on the pencil iteself, to me, but a good creative idea and a nice change of pace from chopsticks.</td>', 'the lighting is a litte strong on the pencil iteself, to me, but a good creative idea and a nice change of pace from chopsticks.', '2007-10-18 00:21:49.000000', NULL, 1),
