(4179132, 599003, 84736, '<td valign="top">very creative. i feel as though the pic might be a little overexposed however. otherwise, good color and composition.</td>', 'very creative. i feel as though the pic might be a little overexposed however. otherwise, good color and composition.', '2007-10-18 16:57:51.000000', NULL, 1),
(4179133, 601239, 84736, '<td valign="top">the lighting on this shot is great, but i feel as though a different backround should be used. This one competes and takes away from the pencil because their color is so similar. other than that, nice pic.</td>', 'the lighting on this shot is great, but i feel as though a different backround should be used. This one competes and takes away from the pencil because their color is so similar. other than that, nice pic.', '2007-10-18 16:57:57.000000', NULL, 1),
(4179138, 601073, 84736, '<td valign="top">wicked cool effect w/ the slow shutter speed and lighting. would be nice to see a little more of the hand to portray it as a fan, but can see why it would have been difficult.</td>', 'wicked cool effect w/ the slow shutter speed and lighting. would be nice to see a little more of the hand to portray it as a fan, but can see why it would have been difficult.', '2007-10-18 16:59:58.000000', NULL, 1),
(4179146, 600581, 84736, '<td valign="top">good focus and angle. maybe some fins on the pencil to make it look a little more like an arrow, but the title drives home the point...</td>', 'good focus and angle. maybe some fins on the pencil to make it look a little more like an arrow, but the title drives home the point...', '2007-10-18 17:01:08.000000', NULL, 1),
(4179154, 600968, 84736, '<td valign="top">great concept. the focus seems a tad soft, but the hogh contrast could be throwing me off. question-did you know the pencil would have that effect when you burned it, or was that by chance?</td>', 'great concept. the focus seems a tad soft, but the hogh contrast could be throwing me off. question-did you know the pencil would have that effect when you burned it, or was that by chance?', '2007-10-18 17:04:30.000000', NULL, 1),
