(4179753, 601097, 41675, '<td valign="top">One of the better chopsticks entry. Good, complimentary background, and good lighting too. Nicely done.</td>', 'One of the better chopsticks entry. Good, complimentary background, and good lighting too. Nicely done.', '2007-10-18 22:12:20.000000', NULL, 1),
(4179756, 601008, 41675, '<td valign="top">I like the additional elements of the hot pads in your setup. Shows additional creativity over other chopstick entries. I also like the symmetry of your photo. The top corners are a bit dark, a bit more lighting or contrast might have helped the white bowls appear more white.</td>', 'I like the additional elements of the hot pads in your setup. Shows additional creativity over other chopstick entries. I also like the symmetry of your photo. The top corners are a bit dark, a bit more lighting or contrast might have helped the white bowls appear more white.', '2007-10-18 22:13:47.000000', NULL, 1),
(4179769, 598524, 41675, '<td valign="top">Interesting image. I like the forms and colors, but there''s something about the lighting that looks a bit...odd to me. I wonder if the middle area is suppose to be white and not yellow?</td>', 'Interesting image. I like the forms and colors, but there''s something about the lighting that looks a bit...odd to me. I wonder if the middle area is suppose to be white and not yellow?', '2007-10-18 22:16:43.000000', NULL, 1),
(4179773, 600555, 41675, '<td valign="top">I read your title and before my eyes fully looked at your photo my brain imagined they would all be wearing little numbers around their "necks." Lol. Nice, clean, simple image - I kind of like that - and no chopsticks!! Hooray!</td>', 'I read your title and before my eyes fully looked at your photo my brain imagined they would all be wearing little numbers around their "necks." Lol. Nice, clean, simple image - I kind of like that - and no chopsticks!! Hooray!', '2007-10-18 22:18:02.000000', NULL, 1),
(4179774, 600832, 85403, '<td valign="top">It''s a pencil in an LP.  Sorry, doesn''t do much for me.  The image seems flat.  This photo could have benifited from a more unique perspective or some more dramatic lighting.</td>', 'It''s a pencil in an LP.  Sorry, doesn''t do much for me.  The image seems flat.  This photo could have benifited from a more unique perspective or some more dramatic lighting.', '2007-10-18 22:18:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4179777, 600805, 85403, '<td valign="top">I love this photo.  Great drama and detail, right down to the smoke rising from the pencil''s eraser!</td>', 'I love this photo.  Great drama and detail, right down to the smoke rising from the pencil''s eraser!', '2007-10-18 22:18:59.000000', NULL, 1),
(4179779, 599071, 41675, '<td valign="top">Clean, good solid background compliments the blue pot and leaves. Good lighting. For me, a good entry all around. Best of luck in the challenge.</td>', 'Clean, good solid background compliments the blue pot and leaves. Good lighting. For me, a good entry all around. Best of luck in the challenge.', '2007-10-18 22:19:21.000000', NULL, 1),
(4179788, 601002, 41675, '<td valign="top">For me, the numbers are the main focal point and it actually took my eyes a moment to find the pencil. Kind of like a "Where''s Waldo" :-) The subject matter doesn''t hold my interest for long, but I do like the lighting and shadows.</td>', 'For me, the numbers are the main focal point and it actually took my eyes a moment to find the pencil. Kind of like a "Where''s Waldo" :-) The subject matter doesn''t hold my interest for long, but I do like the lighting and shadows.', '2007-10-18 22:21:56.000000', NULL, 1),
(4179791, 600580, 41675, '<td valign="top">The first thing to catch my eye was the wrist tatoo and the noodles have the same curly shape. Then I notice the thin, almost curly lines of the flower on the tray. A well balanced setup. In some ways, to me, the stark white background makes it look as if the tray and matt are floating, but a good image overall.</td>', 'The first thing to catch my eye was the wrist tatoo and the noodles have the same curly shape. Then I notice the thin, almost curly lines of the flower on the tray. A well balanced setup. In some ways, to me, the stark white background makes it look as if the tray and matt are floating, but a good image overall.', '2007-10-18 22:23:36.000000', NULL, 1),
(4179796, 600809, 41675, '<td valign="top">Lol - you definitely get a point (or two) for creativity. For me, if the lighting were different, it would be more effective.</td>', 'Lol - you definitely get a point (or two) for creativity. For me, if the lighting were different, it would be more effective.', '2007-10-18 22:26:18.000000', NULL, 1),
(4179801, 600805, 41675, '<td valign="top">Good black &amp; white image - great contrast. You did so well disguising the pencil, I can''t even tell it is one. Good luck in the challenge.</td>', 'Good black & white image - great contrast. You did so well disguising the pencil, I can''t even tell it is one. Good luck in the challenge.', '2007-10-18 22:28:54.000000', NULL, 1),
(4179804, 600272, 41675, '<td valign="top">For me, had the background been dirt, it would be more effective. I like your idea behind it though.</td>', 'For me, had the background been dirt, it would be more effective. I like your idea behind it though.', '2007-10-18 22:29:39.000000', NULL, 1),
(4179805, 599261, 41675, '<td valign="top">Tee hee. Cute idea. It looks a little oversharpened, but good composition and creative idea.</td>', 'Tee hee. Cute idea. It looks a little oversharpened, but good composition and creative idea.', '2007-10-18 22:30:20.000000', NULL, 1),
(4179950, 599211, 64446, '<td valign="top">A little oof, but interesting composition and story...</td>', 'A little oof, but interesting composition and story...', '2007-10-18 23:43:04.000000', NULL, 1),
(4180030, 601106, 84907, '<td valign="top">I like the image.  The white rice does seem to draw my eye to the dirty fingernails though.  Still like the image and will score it well, but something to note.</td>', 'I like the image.  The white rice does seem to draw my eye to the dirty fingernails though.  Still like the image and will score it well, but something to note.', '2007-10-19 00:17:23.000000', NULL, 1),
(4180070, 600790, 81301, '<td valign="top">very good use of DOF.</td>', 'very good use of DOF.', '2007-10-19 00:29:37.000000', NULL, 1),
(4180101, 600791, 81301, '<td valign="top">cool light!</td>', 'cool light!', '2007-10-19 00:36:07.000000', NULL, 1),
(4180106, 601152, 81301, '<td valign="top">you used 3 flashes for this shot which was good to create a movement for the hamer but your pencil is very "hot" as a result...</td>', 'you used 3 flashes for this shot which was good to create a movement for the hamer but your pencil is very "hot" as a result...', '2007-10-19 00:39:00.000000', NULL, 1),
(4180121, 601192, 81301, '<td valign="top">next best thing to Pinocchio!</td>', 'next best thing to Pinocchio!', '2007-10-19 00:46:06.000000', NULL, 1),
(4180132, 599682, 81301, '<td valign="top">good idea and execution.</td>', 'good idea and execution.', '2007-10-19 00:52:25.000000', NULL, 1),
(4180144, 601008, 81301, '<td valign="top">love the trays and the shavings in the bowls.</td>', 'love the trays and the shavings in the bowls.', '2007-10-19 00:57:53.000000', NULL, 1),
(4180174, 600832, 81301, '<td valign="top">just wish that you had the whole round label in the photo and that you didnt cut the apple...</td>', 'just wish that you had the whole round label in the photo and that you didnt cut the apple...', '2007-10-19 01:13:31.000000', NULL, 1),
(4180282, 601008, 26001, '<td valign="top">very simple with nice color pallet. the mat, noodles, chop-sticks everything just perfect. not a fan of dull-white though...one of my favourites 9</td>', 'very simple with nice color pallet. the mat, noodles, chop-sticks everything just perfect. not a fan of dull-white though...one of my favourites 9', '2007-10-19 02:30:07.000000', NULL, 1),
(4180295, 600975, 26001, '<td valign="top">beautiful choice of colors. simpler glasses would have been much better. also 2/3 olives are looking too busy. one is fine. 8</td>', 'beautiful choice of colors. simpler glasses would have been much better. also 2/3 olives are looking too busy. one is fine. 8', '2007-10-19 02:33:40.000000', NULL, 1),
(4180489, 600945, 66353, '<td valign="top">Nice idea - but I wish something was in focus</td>', 'Nice idea - but I wish something was in focus', '2007-10-19 04:30:40.000000', NULL, 1),
(4180503, 600721, 66353, '<td valign="top">I believe the idea was to have a pencil in the picture...</td>', 'I believe the idea was to have a pencil in the picture...', '2007-10-19 04:39:26.000000', NULL, 1),
(4180540, 599158, 84656, '<td valign="top">Nicely done.  Seems a tad overexposed, on the vest bit anyway, colours a bit cold.  Very pretty girl, and those eye''s are pinsharp with nice catchlights.  <br/> <br/>From a portrait perspective, image feels a bit heavy on the bottom.  Reckon cropping 5 rows down from her shirt would give it better balance.</td>', 'Nicely done.  Seems a tad overexposed, on the vest bit anyway, colours a bit cold.  Very pretty girl, and those eye''s are pinsharp with nice catchlights.   From a portrait perspective, image feels a bit heavy on the bottom.  Reckon cropping 5 rows down from her shirt would give it better balance.', '2007-10-19 06:14:04.000000', NULL, 1),
(4180570, 600790, 84656, '<td valign="top">Great pic.  Doesn''t meet the challenge for me though.</td>', 'Great pic.  Doesn''t meet the challenge for me though.', '2007-10-19 06:56:52.000000', NULL, 1),
