(4183267, 601145, 70689, '<td valign="top">Nice idea. I think focus on the pencil and a deeper DOF might have worked better. (5)</td>', 'Nice idea. I think focus on the pencil and a deeper DOF might have worked better. (5)', '2007-10-20 15:59:56.000000', NULL, 1),
(4183268, 599003, 70689, '<td valign="top">Cool! Had to look twice. (8)</td>', 'Cool! Had to look twice. (8)', '2007-10-20 16:00:35.000000', NULL, 1),
(4183293, 601114, 54778, '<td valign="top">Not sure the sepia is helping the picture.. but I like the angle</td>', 'Not sure the sepia is helping the picture.. but I like the angle', '2007-10-20 16:18:42.000000', NULL, 1),
(4183301, 600641, 54778, '<td valign="top">This is a nice picture.. it lacks in the composition department.. just using more negative space would have helped..</td>', 'This is a nice picture.. it lacks in the composition department.. just using more negative space would have helped..', '2007-10-20 16:23:23.000000', NULL, 1),
(4183303, 599636, 54778, '<td valign="top">the food looks appetizing even to me though I wouldn''t touch it in real life so that''s a compliment..I like the colours and everything.. the composition could have been improved and the lighting looks odd so half and half in the composition..  The background is way too bright.. maybe if it was evenly all that bright it would have worked better..</td>', 'the food looks appetizing even to me though I wouldn''t touch it in real life so that''s a compliment..I like the colours and everything.. the composition could have been improved and the lighting looks odd so half and half in the composition..  The background is way too bright.. maybe if it was evenly all that bright it would have worked better..', '2007-10-20 16:26:00.000000', NULL, 1),
(4183305, 599076, 54778, '<td valign="top">okay, I do get it.. and it''s amusing. wish you''d chosen a better background and lighting.. pink and fuzzy just isn''t the best background.. maybe buying some white/black/primary coloured matt chart paper would help for future backgrounds..</td>', 'okay, I do get it.. and it''s amusing. wish you''d chosen a better background and lighting.. pink and fuzzy just isn''t the best background.. maybe buying some white/black/primary coloured matt chart paper would help for future backgrounds..', '2007-10-20 16:27:28.000000', NULL, 1),
(4183307, 601106, 54778, '<td valign="top">Like the perspective on this one..</td>', 'Like the perspective on this one..', '2007-10-20 16:29:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4183367, 601008, 85399, '<td valign="top">The most unique of all the chopsticks</td>', 'The most unique of all the chopsticks', '2007-10-20 17:29:12.000000', NULL, 1),
(4183369, 600791, 85399, '<td valign="top">not a pencil</td>', 'not a pencil', '2007-10-20 17:29:31.000000', NULL, 1),
(4183376, 599777, 85399, '<td valign="top">Very different</td>', 'Very different', '2007-10-20 17:32:52.000000', NULL, 1),
(4183378, 601095, 85399, '<td valign="top">like the use of other office pieces</td>', 'like the use of other office pieces', '2007-10-20 17:34:00.000000', NULL, 1),
(4183550, 600084, 42181, '<td valign="top">Ha Ha , i stick my tongue out when i''m concentrating. Good use of the shallow DOF.</td>', 'Ha Ha , i stick my tongue out when i''m concentrating. Good use of the shallow DOF.', '2007-10-20 19:03:38.000000', NULL, 1),
(4183564, 601017, 41675, '<td valign="top">:-) I like it. Good composition. The solid black background doesn''t detract, if anything it makes the colored pencils pop even better. Good lighting too. I hope this does well in the challenge for you.</td>', ':-) I like it. Good composition. The solid black background doesn''t detract, if anything it makes the colored pencils pop even better. Good lighting too. I hope this does well in the challenge for you.', '2007-10-20 19:16:52.000000', NULL, 1),
(4183566, 598846, 41675, '<td valign="top">This would be a good advertisement shot for this toy. I like the lighting and the photo background worrks well. Plus, it does kind of resemble my boss at times. Lol</td>', 'This would be a good advertisement shot for this toy. I like the lighting and the photo background worrks well. Plus, it does kind of resemble my boss at times. Lol', '2007-10-20 19:17:41.000000', NULL, 1),
(4183568, 599076, 41675, '<td valign="top">For me, the lighting is a bit too harsh and the background is so busy it detracts. I like your overall idea/concept though - it shows creativity.</td>', 'For me, the lighting is a bit too harsh and the background is so busy it detracts. I like your overall idea/concept though - it shows creativity.', '2007-10-20 19:18:31.000000', NULL, 1),
(4183570, 601012, 41675, '<td valign="top">For me, without your title it might be hard to understand what your intent was. I do like the triangular composition of the three vertical elements though. Good lighting and the perspective is fun.</td>', 'For me, without your title it might be hard to understand what your intent was. I do like the triangular composition of the three vertical elements though. Good lighting and the perspective is fun.', '2007-10-20 19:19:53.000000', NULL, 1),
(4183572, 598783, 41675, '<td valign="top">..and a patriotic dinner at that. :-) Cute idea. I like the minimalistic approach of your image. I am curious how this would look with a darker background.</td>', '..and a patriotic dinner at that. :-) Cute idea. I like the minimalistic approach of your image. I am curious how this would look with a darker background.', '2007-10-20 19:20:38.000000', NULL, 1),
(4183587, 599788, 41675, '<td valign="top">For me, your image doesn''t fully communicate that it''s something other than a pencil without having your title. Good composition and lighting though.</td>', 'For me, your image doesn''t fully communicate that it''s something other than a pencil without having your title. Good composition and lighting though.', '2007-10-20 19:24:45.000000', NULL, 1),
(4183591, 599211, 41675, '<td valign="top">Your image appears pixelated or over sharpened to me. I like the composition though.</td>', 'Your image appears pixelated or over sharpened to me. I like the composition though.', '2007-10-20 19:25:30.000000', NULL, 1),
(4183598, 599443, 41675, '<td valign="top">Tee hee, cute photo. I like the reflection and the silver cup. This is being picky, but I would have cloned out those little spots around the shavings. Good colors and composition too.</td>', 'Tee hee, cute photo. I like the reflection and the silver cup. This is being picky, but I would have cloned out those little spots around the shavings. Good colors and composition too.', '2007-10-20 19:26:33.000000', NULL, 1),
(4183602, 600106, 41675, '<td valign="top">If your image was a bit sharper or the "laser" a bit more pronounced, I would have scored it higher. Point for originality though. :-)</td>', 'If your image was a bit sharper or the "laser" a bit more pronounced, I would have scored it higher. Point for originality though. :-)', '2007-10-20 19:27:32.000000', NULL, 1),
(4183607, 600611, 41675, '<td valign="top">Aside from the odd pinkish/red color on the middle of the "straw," I like your image. Creative and fun.</td>', 'Aside from the odd pinkish/red color on the middle of the "straw," I like your image. Creative and fun.', '2007-10-20 19:28:40.000000', NULL, 1),
(4183874, 599182, 73250, '<td valign="top">I''m sorry, your frame over takes your image.</td>', 'I''m sorry, your frame over takes your image.', '2007-10-20 22:13:37.000000', NULL, 1),
(4183878, 600739, 83313, '<td valign="top">A good view. It almost looks like it is the size of a log.</td>', 'A good view. It almost looks like it is the size of a log.', '2007-10-20 22:15:15.000000', NULL, 1),
(4183880, 601056, 83313, '<td valign="top">a good concept, but some more color may have helped it.</td>', 'a good concept, but some more color may have helped it.', '2007-10-20 22:15:52.000000', NULL, 1),
(4183883, 600438, 83313, '<td valign="top">I had to have a second look to see that the pencils were broken and stuffed in the glass. Good conveyance of the idea, great composition.</td>', 'I had to have a second look to see that the pencils were broken and stuffed in the glass. Good conveyance of the idea, great composition.', '2007-10-20 22:17:44.000000', NULL, 1),
(4183884, 599158, 83313, '<td valign="top">Every girl in middle school will want one now!</td>', 'Every girl in middle school will want one now!', '2007-10-20 22:18:48.000000', NULL, 1),
(4183886, 600624, 83313, '<td valign="top">Very well done. Reminds me of "Beaker" from the Muppet show.</td>', 'Very well done. Reminds me of "Beaker" from the Muppet show.', '2007-10-20 22:19:25.000000', NULL, 1),
(4183901, 599966, 6519, '<td valign="top">This is quite an attractive photo. I like the diagonal, and the way that motley background emphasizes the pretty colors.<br/>However, the connection to the challenge topic is only marginal.</td>', 'This is quite an attractive photo. I like the diagonal, and the way that motley background emphasizes the pretty colors.However, the connection to the challenge topic is only marginal.', '2007-10-20 22:29:22.000000', NULL, 1),
(4183905, 600721, 6519, '<td valign="top">I assume you were trying for the brown ribbon? Don''t worry if you don''t make it - at least yours is the one and only submission in this challenge that has absolutely nothing to do with the topic.</td>', 'I assume you were trying for the brown ribbon? Don''t worry if you don''t make it - at least yours is the one and only submission in this challenge that has absolutely nothing to do with the topic.', '2007-10-20 22:31:28.000000', NULL, 1),
