(4184039, 599682, 84106, '<td valign="top">OK, you get 10 for this one! great concept, beautiful composition, lighting, focus. 10.</td>', 'OK, you get 10 for this one! great concept, beautiful composition, lighting, focus. 10.', '2007-10-20 23:40:58.000000', NULL, 1),
(4184048, 601012, 84106, '<td valign="top">ya gotta love it. great concept, execution, title. don''t like the scruffy trees - what can you do. good DOF. 8.</td>', 'ya gotta love it. great concept, execution, title. don''t like the scruffy trees - what can you do. good DOF. 8.', '2007-10-20 23:46:00.000000', NULL, 1),
(4184051, 600113, 84106, '<td valign="top">Yummy. great concept, composition, lighting. 8.</td>', 'Yummy. great concept, composition, lighting. 8.', '2007-10-20 23:47:42.000000', NULL, 1),
(4184057, 600805, 84106, '<td valign="top">I love it! great concept, composition. background is wrong - blends too much with hat. good use of b&amp;w. 8.</td>', 'I love it! great concept, composition. background is wrong - blends too much with hat. good use of b&w. 8.', '2007-10-20 23:52:24.000000', NULL, 1),
