(4184100, 600896, 35530, '<td valign="top">Now that''s an ugly pencil...but a very nice composition.</td>', 'Now that''s an ugly pencil...but a very nice composition.', '2007-10-21 00:18:18.000000', NULL, 1),
(4184103, 601128, 35530, '<td valign="top">Ah! That''s where they come from.</td>', 'Ah! That''s where they come from.', '2007-10-21 00:19:33.000000', NULL, 1),
